import{_ as r,a0 as i,w as n,s as l,ao as a,I as u,x as t,a1 as p,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const I=JSON.parse('{"title":"戴文的Linux內核專題：06 內核配置(2) | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux內核專題：06 內核配置(2) | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux內核專題：06 內核配置(2) | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux內核專題：06 內核配置(2) | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/06 The Linux Kernel--Configuring the Kernel Part 2","title":"戴文的Linux內核專題：06 內核配置(2)","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/06 The Linux Kernel--Configuring the Kernel Part 2.md","filePath":"[post].md"}'),C={name:"The Linux Kernel/06 The Linux Kernel--Configuring the Kernel Part 2.md"};function U(c,e,_,g,T,R){const o=i("Link");return n(),l("div",null,[e[11]||(e[11]=a('<h1 id="戴文的linux內核專題-06-內核配置-2" tabindex="-1">戴文的Linux內核專題：06 內核配置(2) <a class="header-anchor" href="#戴文的linux內核專題-06-內核配置-2" aria-label="Permalink to “戴文的Linux內核專題：06 內核配置(2)”">​</a></h1><p><img src="http://www.linux.org/attachments/slide-jpg.351/" alt=""></p><p>這一部分我們講配置內核IRQ子系統。中斷請求(IRQ)是硬件發給處理器的一個信號，它暫時停止一個正在運行的程序並允許一個特殊的程序佔用CPU運行。</p><p>這個目錄中的第一個問題屬於內核特性(Expose hardware/virtual IRQ mapping via debugfs (IRQ_DOMAIN_DEBUG))（通過debugfs來顯示硬件/虛擬的IRQ映射），它詢問是否可以使用虛擬的調試文件系統來映射硬件及Linux上對應的IRQ中斷號。這個用作調試目的，大多數用户不需要用到，所以我選擇了&quot;no&quot;。</p><p>下一個標題顯示&quot;Timers subsystem&quot;（計時器子系統）。第一個有關定時器子系統的問題是“Tickless System (Dynamic Ticks) (NO_HZ)”（無滴答系統）。我選擇了“yes”，這會啓用一個無滴答系統。這意味着定時器中斷將會按需使用，定時器中斷允許任務以特定的時間間隔執行。下一個問題(High Resolution Timer Support (HIGH_RES_TIMERS))問是否支持高精度定時器。並不是所有的硬件支持這個，通常地説，如果硬件很慢或很舊，那麼選擇&quot;no&quot;,否則像我一樣選擇&quot;yes&quot;。</p><p>下一個標題&quot;CPU/Task time and stats accounting&quot;（CPU/任務用時與狀態統計），這個是關於進程的追蹤。第一個問題看上去像這樣：</p><p>Cputime accounting （CPU用時統計）</p><ol><li>Simple tick based cputime accounting (TICK_CPU_ACCOUNTING) （簡單基於滴答的用時統計）</li><li>Full dynticks CPU time accounting (VIRT_CPU_ACCOUNTING_GEN) (NEW) （全動態滴答的用時統計）</li><li>Fine granularity task level IRQ time accounting (IRQ_TIME_ACCOUNTING) （細粒度的任務級IRQ用時統計）</li></ol><p>TICK_CPU_ACCOUNTING會在每個CPU滴答中檢測/proc/stat。這是默認的選項，這個記賬方法非常簡單。</p><p>注意：CPU滴答是抽象測量CPU時間的方式。每個處理器、操作系統和安裝的系統都不同，比如説，一個更強大的處理器會比老的處理器擁有更多的CPU滴答。如果你安裝了一個Linux系統，然後接着在同一塊磁盤上重新安裝了它，你可能會得到一個更快或更慢的CPU滴答時間(至少一些計算機技術書上這麼説)。通常來講，一個更快的時鐘速度意味着更多的CPU滴答。</p><p>如果啓用了VIRT_CPU_ACCOUNTING_GEN，任務和CPU時間統計將由監視內核-用户邊界實現。這個選擇的代價是會增加額外的開銷。</p><p>IRQ_TIME_ACCOUNTING記賬方式則通過檢測IRQ狀態間的時間戳工作，這個性能開銷很小。</p><p>我選擇了&quot;1&quot;並被詢問有關BSD記賬&quot;BSD Process Accounting (BSD_PROCESS_ACCT)&quot;（BSD進程記賬）的問題。這個內核特性會記錄每個進程不同的關閉信息。為了得到一個更小和更快的內核，我選擇了&quot;no&quot;.</p><p>下一組問題看上去就像下面這樣。</p><ul><li>Export task/process statistics through netlink (TASKSTATS) （通過netlink導出任務/進程統計數據）</li><li>Enable per-task delay accounting (TASK_DELAY_ACCT) （啓用針對每個任務的延遲統計）</li><li>Enable extended accounting over taskstats (TASK_XACCT) （啓用taskstats的擴展統計）</li></ul><p>TASKSTATS使內核可以通過網絡套接字導出進程統計。網絡套接字是內核和用户空間進程間IPC通信的一種形式。TASK_DELAY_ACCT監視進程並注意資源訪問的延遲。比如，TASK_DELAY_ACCT可以看到X進程正在為了CPU時間而等待，如果TASK_DELAY_ACCT觀察到進程已經等待了太長時間，這個進程接着就會被給予一些CPU時間。TASK_XACCT會收集額外的統計數據，為了更小的內核負載我會禁用這個。</p><p>現在接下來的目錄就會顯示RCU子系統：讀取-複製-更新子系統是一種低負載的同步機制，它允許程序查看到正在被修改/更新的文件。配置工具已經回答了第一個問題。</p><p>RCU Implementation （RCU 實現方式）</p><p>&gt; 1. Tree-based hierarchical RCU (TREE_RCU) （樹形分層結構的RCU）</p><p>choice[1]: 1</p><p>這裏就選擇“1”。除了TREE_RCU，還有classic RCU(更老的實現)。下一個問題(Consider userspace as in RCU extended quiescent state (RCU_USER_QS) [N/y/?])（是否在用户空間記錄擴展的quiescent狀態）問RCU是否可以在CPU運行在用户空間時設置一個特殊的quiescent狀態。這個選項通常被禁用，因為這會增加太多消耗。下面是另一個RCU問題(Tree-based hierarchical RCU fanout value (RCU_FANOUT) [64])（樹形分層結構的RCU端點數），問的是關於端點數。下一個問題(Tree-based hierarchical RCU leaf-level fanout value (RCU_FANOUT_LEAF) [16])（樹形分層結構的RCU葉級端點數），是另外一個關於端點數的問題，但它只處理葉級。還有另外一個RCU問題(Disable tree-based hierarchical RCU auto-balancing (RCU_FANOUT_EXACT) [N/y/?])（是否禁用樹形分層結構的RCU的自動平衡），詢問是否禁用RCU自動平衡樹，而採用上述的端點數。</p><p>接下來，配置腳本將會詢問&quot;Accelerate last non-dyntick-idle CPU&#39;s grace periods (RCU_FAST_NO_HZ)&quot;（加速最後的非dyntick-idle CPU的RCU寬限期）。在這之後會顯示&quot;Offload RCU callback processing from boot-selected CPUs (RCU_NOCB_CPU)&quot;（從選擇引導的CPU裏面卸載RCU回調）。（譯註：此處作者沒做解釋。前一個能夠節省電力，但是降低了性能；後一個用於調試。）</p><p>下一個問題非常重要(Kernel .config support (IKCONFIG))（內核的.config支持）。開發人員可以選擇保存由這個配置工具生成的設置到一個文件中。這個文件可以放在內核中，也可在一個模組中，或者完全不保存。這個文件可以被想要編譯一個完全跟某人相同內核的開發者使用。這個文件還可以幫助開發人員使用一個更新的編譯器重新編譯一個內核。舉例來説，開發人員配置並編譯了一個內核，然而編譯器有一些bug，但開發人員仍然需要一個使用這些設置的內核。而值得慶幸的是，開發人員可以升級他們的編譯器，並使用設置文件來節省他們重新配置內核的時間。開發人員也可以在另一台計算機上保存源代碼和配置文件並編譯內核。至於另一個目的，開發人員可以加載該文件，並根據需要調整設置。我選擇保存配置文件在一個模組中，這個問題 &quot;Enable access to .config through /proc/config.gz (IKCONFIG_PROC)&quot;（啓用通過/proc/config.gz來訪問.config的功能）是詢問這個文件是否是可以通過這次方式訪問的，我選擇了&quot;yes&quot;。</p><p>下一個問題是內核使用多大的log緩衝區(Kernel log buffer size (16 =&gt; 64KB, 17 =&gt; 128KB) (LOG_BUF_SHIFT) [17])（內核日誌緩衝區大小）。小的緩衝區意味着它無法像更大的緩衝區那樣保持日誌更長的時間。這個選擇取決於開發者想要日誌保持的時間，我選擇的是&quot;12&quot;。</p><p>接着，出現了另外一個問題。該問題詢問關於是否啓用NUMA(非一致性內存訪問)的內存/任務的均衡(Automatically enable NUMA aware memory/task placement (NUMA_BALANCING_DEFAULT_ENABLED))（自動啓用NUMA的內存/任務均衡）。如果在NUMA的機器上設置了該選項，那麼NUMA自動平衡就會啓用。在NUMA下，處理器可以比非本地內存(內存分配給另外一個處理器或在處理器之間共享的內存)更快地訪問它的本地內存。如果上面啓用了(我啓用了)，那麼最好對這個問題&quot;Memory placement aware NUMA scheduler (NUMA_BALANCING)&quot;（由NUMA調度器進行內存分配）回答&quot;yes&quot;，這是一個NUMA調度器。</p><p>在新的標題&quot;Control Group support&quot;（Cgroup支持）下，因為先前的選擇，&quot;Control Group support (CGROUPS)&quot;（Cgroup支持）被自動地回答了&quot;yes&quot;。</p><p>以下設定(Example debug cgroup subsystem (CGROUP_DEBUG))（導出Cgroup子系統的調試信息）是啓用一個用於調試cgroup框架的一個簡單cgroup子系統。下一個選項(Freezer cgroup subsystem (CGROUP_FREEZER))（凍結Cgroup子系統）可以讓程序員可以凍結或解凍cgroup內的任務。</p><p>注意：cgroup是一組進程。</p><p>下面我們要求回答&quot;Device controller for cgroups (CGROUP_DEVICE)&quot;(Cgroup的設備控制器)。cgroup(控制組)是一種用來控制資源使用的特性。回答&quot;yes&quot;可以允許設備cgroup的白名單可以使用open和mknod系統調用(用來創建文件系統節點的系統調用)。</p><p>下一個問題(Cpuset support (CPUSETS))（CPU分組支持）詢問的是內核是否可以創建和管理CPU分組。這允許管理員可以在一個系統上動態分配各組內存節點，並分配任務在這些內存上運行。這通常用於SMP和NUMA系統中。我這個問題回答的是&quot;no&quot;。</p><p>注意：請記住，如果我沒有指定我選的是什麼，那麼我選的就是默認選項。</p><p>啓用cgroup統計子系統(Simple CPU accounting cgroup subsystem (CGROUP_CPUACCT))（Cgroup子系統的簡單CPU統計）會生成一個資源控制器來監控在一個cgroup組內的獨立任務的CPU使用情況。我選擇了&quot;no&quot;。</p><p>資源計數器(Resource counters (RESOURCE_COUNTERS))使控制器的獨立資源統計功能能夠統計cgroup。我選擇了&quot;no&quot;。</p><p>下一個問題(Enable perf_event per-cpu per-container group (cgroup) monitoring (CGROUP_PERF))（啓用每個CPU、每個容器組的pref_event監控）允許開發者擴展每個CPU的模式，使它可以只監控運行在特定CPU上的一個特別的cgroup組的線程。</p><p>下一章節是&quot;Group CPU Scheduler&quot;（CPU分組調度器）。前兩個已經回答的問題包括：</p><p>Group CPU scheduler (CGROUP_SCHED)（CPU分組調度器） Group scheduling for SCHED_OTHER (FAIR_GROUP_SCHED)（SCHED_OTHER分組調度）</p><p>第一個已回答的問題(CPU bandwidth provisioning for FAIR_GROUP_SCHED (CFS_BANDWIDTH))（CPU帶寬分配）詢問的是內核是否允許用户設置在公平組調度器內執行的任務的CPU帶寬限制。沒有限制的組會被認為不受約束，並會沒有限制地運行。</p><p>注意：並不是所有內核選項都在這裏。我這裏提到的組只是為了便於閲讀，並挑出那些新的和大的部分。並不需要了解所有的分組。分組有助於使用圖形工具配置內核，這樣開發者可以在搜索特定的設置時，直接通過分組菜單找到。</p><p>開發者可以通過回答&quot;Group scheduling for SCHED_RR/FIFO (RT_GROUP_SCHED)&quot;（SCHED_RR/FIFO分組調度）這個問題為&quot;yes&quot;來讓用户可以分配CPU帶寬到任務組中。</p><p>下一個問題是&quot;Block IO controller (BLK_CGROUP)&quot;（阻塞IO控制器）。任務組可以被識別，並且它們的磁盤帶寬是由使用塊IO控制器實現的CFQ IO調度器分配的。BIO在塊級的限制邏輯使用塊IO控制器來提供設備上的IO速率上限。</p><p>這裏有一個調試問題(Enable Block IO controller debugging (DEBUG_BLK_CGROUP) [N/y/?])（啓用阻塞IO控制器的調試）詢問是否啓用塊IO控制器的調試。為了製作一個精簡的內核，最好禁用這個特性。</p><p>為了啓用內核中的檢查點和還原特性。這個問題“Checkpoint/restore support (CHECKPOINT_RESTORE)”（檢查點及還原支持）可以選擇“yes”，不過為了更低的負載這裏我選擇了“n”。啓用這個特性會增加輔助的進程控制代碼來設置進程的代碼段、數據段和堆的大小，並增加了一些額外的程序入口。</p><p>下面我們就要配置命名空間的支持了。命名空間是一組標識符的容器。比如，/usr/lib/python3/dist-packages/re.py就是一個標識符，/usr/lib/python3/dist-packages/就是一個命名空間。而re.py是這個命名空間下的本地名稱。</p><p>第一個命名空間問題(Namespaces support (NAMESPACES))詢問的是是否啓用命名空間。這允許可以使用相同的PID但在不同的命名空間內(譯註：原文為&quot; This will allow the same PIDs (Process ID) to be used but indifferent namespaces&quot;,這裏indiffernt根據上下文應該是少了空格)，否則PID永遠不會重複。</p><p>下一個問題(UTS namespace (UTS_NS))詢問是否可以讓UTS命名空間內的任務可以在uname()系統調用中看到不同的信息。uname()系統調用提供查看機器和操作系統的信息。</p><p>啓用IPC命名空間(IPC namespace (IPC_NS))將允許在這個命名空間內的任務與其他命名空間內相對應IPC ID的對象協同工作。</p><p>PID命名空間(PID Namespaces (PID_NS))就是進程ID命名空間。這可以使不同的進程在不同的PID命名空間使用相同的PID。這是一個容器的構建塊。</p><p>接下來，啓用網絡命名空間(Network namespace (NET_NS))可以使用户創建一個擁有多個實例的網絡棧。</p><p>當啓用後,自動進程分組調度(SCHED_AUTOGROUP)會填充並創建任務組來優化桌面程序的調度。它將把佔用大量資源的應用程序放在它們自己的任務組，這有助於性能提升。</p><p>這裏是一個調試特性，除非你有特別的需求否則應該禁用它。這個問題(Enable deprecated sysfs features to support old userspace tools (SYSFS_DEPRECATED))（啓用不推薦的sysfs功能來支持舊式的用户空間工具）詢問是否啓用sysfs，這是調試內核時用的虛擬文件系統。</p><p>接下來，因為當前的配置需要它，所以&quot;Kernel-&gt;user space relay support (formerly relayfs) (RELAY)&quot;（內核-&gt;用户空間的中繼支持，即relayfs）已經被設成&quot;yes&quot;了。最好啓用initrd支持(Initial RAM filesystem and RAM disk (initramfs/initrd) support (BLK_DEV_INITRD))（初始化內存文件系統和內存盤(initramfs/initrd)）。</p><p>用户會被問及哪裏放置initramfs源文件。如果沒有需要，請留空。</p><p>接下來,開發人員會被詢問關於初始虛擬磁盤(Linux的內核映像文件)所支持的壓縮格式。你可以啓用所有支持的壓縮格式。</p><ul><li>Support initial ramdisks compressed using gzip (RD_GZIP)</li><li>Support initial ramdisks compressed using bzip2 (RD_BZIP2)</li><li>Support initial ramdisks compressed using LZMA (RD_LZMA)</li><li>Support initial ramdisks compressed using XZ (RD_XZ)</li><li>Support initial ramdisks compressed using LZO (RD_LZO)</li></ul><p>這裏設置了內核的編譯內核編譯選項(Optimize for size (CC_OPTIMIZE_FOR_SIZE))（優化大小）。開發者可以讓編譯器在編譯時優化代碼。我選擇了&quot;yes&quot;。</p><p>用户想要配置更多的內核特性，那麼下個問題就回答&quot;yes&quot;(Configure standard kernel features (expert users) (EXPERT))（配置標準內核特性（專家級用户））。</p><p>要啓用過時的16位UID系統調用封裝器，這個問題設成&quot;yes&quot;(Enable 16-bit UID system calls (UID16))。系統調用就會使用16位UID。</p><p>推薦啓用&quot;sysctl syscall&quot;(Sysctl syscall support (SYSCTL_SYSCALL))支持。這使/proc/sys成為二進制路徑的接口。</p><p>接下來的兩個問題已經被預先回答了&quot;yes&quot;,它們是&quot;Load all symbols for debugging/ksymoops (KALLSYMS)&quot;（載入所以的調試符號）和&quot;“Include all symbols in kallsyms (KALLSYMS_ALL)&quot;（包括所有的kallsyms符號）。這些都是啓用調試標誌。</p><p>下一步，開發者應該啓用printk支持( (Enable support for printk (PRINTK)))，這會輸出內核消息到內核日誌中。這在內核出錯時是很重要的。編譯一個&quot;啞巴&quot;內核並不是一個好主意。然而，如果我們啓用了這個支持，就會被一些開發者看到這些出錯，要麼就不要啓用。</p><p>除非有必要，開發者可以禁用bug支持(BUG() support (BUG))。禁用這項將會不支持WARN信息和BUG信息。這會減小內核的體積。</p><hr>',62)),u("p",null,[e[1]||(e[1]=t("via: ",-1)),p(o,{href:"http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-2.4318/"},{default:s(()=>[...e[0]||(e[0]=[t("http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-2.4318/",-1)])]),_:1})]),u("p",null,[e[4]||(e[4]=t("譯者：",-1)),p(o,{href:"https://github.com/geekpi"},{default:s(()=>[...e[2]||(e[2]=[t("geekpi",-1)])]),_:1}),e[5]||(e[5]=t(" 校對：",-1)),p(o,{href:"https://github.com/wxy"},{default:s(()=>[...e[3]||(e[3]=[t("wxy",-1)])]),_:1})]),u("p",null,[e[8]||(e[8]=t("本文由 ",-1)),p(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原創翻譯，",-1)),p(o,{href:"http://linux.cn/"},{default:s(()=>[...e[7]||(e[7]=[t("Linux中國",-1)])]),_:1}),e[10]||(e[10]=t(" 榮譽推出",-1))])])}const m=r(C,[["render",U]]);export{I as __pageData,m as default};
